+import { useEffect, useRef, useState } from 'react';
+import { useStableCallback } from '../../hooks/useStableCallback';
+import { type CopyButtonProps, type CopyStatus, CopyStatuses } from './CopyButton.types';
+
+interface CopyButtonFacadeProps {
+  text: string;
+  timeout: number;
+  onCopy?: CopyButtonProps['onCopy'];
+  onError?: CopyButtonProps['onError'];
+}
+
+const writeToClipboard = async (text: string) => {
+  if (navigator.clipboard?.writeText) {
+    await navigator.clipboard.writeText(text);
+    return;
+  }
+
+  throw new Error('Clipboard API is not available in this environment.');
+};
+
+const useCopyButtonFacade = ({ text, timeout, onCopy, onError }: CopyButtonFacadeProps) => {
+  const [status, setStatus] = useState<CopyStatus>(CopyStatuses.IDLE);
+  const timeoutRef = useRef<ReturnType<typeof setTimeout>>();
+
+  const scheduleReset = useStableCallback(() => {
+    clearTimeout(timeoutRef.current);
+    timeoutRef.current = setTimeout(() => setStatus(CopyStatuses.IDLE), timeout);
+  }, [timeout]);
+
+  const copy = useStableCallback(async () => {
+    try {
+      await writeToClipboard(text);
+      setStatus(CopyStatuses.COPIED);
+      onCopy?.(text);
+    } catch (error) {
+      setStatus(CopyStatuses.ERROR);
+      onError?.(error);
+    } finally {
+      scheduleReset();
+    }
+  }, [text, onCopy, onError, scheduleReset]);
+
+  useEffect(() => () => clearTimeout(timeoutRef.current), []);
+
+  return { status, copy } as const;
+};
+
+export default useCopyButtonFacade;
