+import { fireEvent, render, screen, waitFor } from '@testing-library/react';
+import { afterEach, beforeEach, describe, expect, it, vi } from 'vitest';
+import CopyButton from './CopyButton';
+
+describe('CopyButton', () => {
+  beforeEach(() => {
+    Object.defineProperty(navigator, 'clipboard', {
+      configurable: true,
+      value: { writeText: vi.fn().mockResolvedValue(undefined) },
+    });
+  });
+
+  afterEach(() => {
+    vi.restoreAllMocks();
+  });
+
+  it('renders the idle label by default', () => {
+    render(<CopyButton text="hello" />);
+    expect(screen.getByRole('button', { name: /copy/i })).toBeInTheDocument();
+  });
+
+  it('writes the text to the clipboard and shows the copied state', async () => {
+    const onCopy = vi.fn();
+    render(<CopyButton text="hello" onCopy={onCopy} />);
+
+    fireEvent.click(screen.getByRole('button'));
+
+    await waitFor(() => expect(navigator.clipboard.writeText).toHaveBeenCalledWith('hello'));
+    expect(await screen.findByText('Copied')).toBeInTheDocument();
+    expect(onCopy).toHaveBeenCalledWith('hello');
+  });
+
+  it('resets to idle after the timeout', async () => {
+    render(<CopyButton text="hello" timeout={50} />);
+
+    fireEvent.click(screen.getByRole('button'));
+    await screen.findByText('Copied');
+
+    await waitFor(() => expect(screen.getByText('Copy')).toBeInTheDocument());
+  });
+
+  it('shows the error state and calls onError when the clipboard write fails', async () => {
+    const failure = new Error('denied');
+    navigator.clipboard.writeText = vi.fn().mockRejectedValue(failure);
+    const onError = vi.fn();
+
+    render(<CopyButton text="hello" onError={onError} />);
+    fireEvent.click(screen.getByRole('button'));
+
+    expect(await screen.findByText('Failed')).toBeInTheDocument();
+    expect(onError).toHaveBeenCalledWith(failure);
+  });
+
+  it('supports a custom label render prop', () => {
+    render(<CopyButton text="hello">{() => 'Copy token'}</CopyButton>);
+    expect(screen.getByRole('button', { name: 'Copy token' })).toBeInTheDocument();
+  });
+});
