+import clsx from 'clsx';
+import type { MouseEventHandler } from 'react';
+import useCopyButtonFacade from './CopyButton.facade';
+import styles from './CopyButton.module.scss';
+import { type CopyButtonProps, type CopyStatus, CopyStatuses } from './CopyButton.types';
+
+const CopyIcon = () => (
+  <svg viewBox="0 0 24 24" fill="none" aria-hidden="true" focusable="false">
+    <rect x="9" y="9" width="11" height="11" rx="2" stroke="currentColor" strokeWidth="2" />
+    <path d="M5 15V5a2 2 0 0 1 2-2h8" stroke="currentColor" strokeWidth="2" strokeLinecap="round" />
+  </svg>
+);
+
+const CheckIcon = () => (
+  <svg viewBox="0 0 24 24" fill="none" aria-hidden="true" focusable="false">
+    <path
+      d="M4 12.5 9 17.5 20 6.5"
+      stroke="currentColor"
+      strokeWidth="2"
+      strokeLinecap="round"
+      strokeLinejoin="round"
+    />
+  </svg>
+);
+
+const DEFAULT_LABELS: Record<CopyStatus, string> = {
+  [CopyStatuses.IDLE]: 'Copy',
+  [CopyStatuses.COPIED]: 'Copied',
+  [CopyStatuses.ERROR]: 'Failed',
+};
+
+const CopyButton = ({
+  text,
+  timeout = 2000,
+  onCopy,
+  onError,
+  children,
+  className,
+  onClick,
+  ...props
+}: CopyButtonProps) => {
+  const { status, copy } = useCopyButtonFacade({ text, timeout, onCopy, onError });
+
+  const handleClick: MouseEventHandler<HTMLButtonElement> = (event) => {
+    onClick?.(event);
+    void copy();
+  };
+
+  return (
+    <button
+      type="button"
+      className={clsx(styles['copy-button'], className)}
+      data-status={status}
+      aria-live="polite"
+      onClick={handleClick}
+      {...props}
+    >
+      <span className={styles['copy-button__icon']}>
+        {status === CopyStatuses.COPIED ? <CheckIcon /> : <CopyIcon />}
+      </span>
+      <span className={styles['copy-button__label']}>
+        {children ? children(status) : DEFAULT_LABELS[status]}
+      </span>
+    </button>
+  );
+};
+
+export default CopyButton;
