+import type React from 'react';
+import type { ValueOf } from '../../types/value-of';
+
+export const CopyStatuses = {
+  IDLE: 'idle',
+  COPIED: 'copied',
+  ERROR: 'error',
+} as const;
+
+export type CopyStatus = ValueOf<typeof CopyStatuses>;
+
+export interface CopyButtonProps
+  extends Omit<React.ButtonHTMLAttributes<HTMLButtonElement>, 'children' | 'onError' | 'onCopy'> {
+  /**
+   * @description The text to write to the clipboard.
+   */
+  text: string;
+  /**
+   * @description How long (ms) the copied/error state persists before resetting to idle.
+   * @default 2000
+   */
+  timeout?: number;
+  /**
+   * @description Fired after the text is successfully copied.
+   */
+  onCopy?: (text: string) => void;
+  /**
+   * @description Fired when writing to the clipboard fails.
+   */
+  onError?: (error: unknown) => void;
+  /**
+   * @description Render prop to customise the label per status. Defaults to built-in labels.
+   */
+  children?: (status: CopyStatus) => React.ReactNode;
+}
